function countSubarraysWithSum(nums, k) {
  let count = 0;
  let prefixSum = 0;
  const prefixMap = new Map();
  prefixMap.set(0, 1);

  for (const num of nums) {
    prefixSum += num;
    const diff = prefixSum - k;
    if (prefixMap.has(diff)) {
      count += prefixMap.get(diff);
    }
    prefixMap.set(prefixSum, (prefixMap.get(prefixSum) || 0) + 1);
  }

  return count;
}

function flattenObject(obj, prefix = '') {
  const result = {};

  for (const key of Object.keys(obj)) {
    const val = obj[key];
    const newKey = prefix ? `${prefix}.${key}` : key;

    if (val !== null && typeof val === 'object' && !Array.isArray(val)) {
      Object.assign(result, flattenObject(val, newKey));
    } else {
      result[newKey] = val;
    }
  }

  return result;
}

function asyncBatchRunner(items, asyncFn, limit = 2) {
  return new Promise((resolve, reject) => {
    const results = new Array(items.length);
    let currentIndex = 0;
    let completedCount = 0;

    if (items.length === 0) return resolve([]);

    function launchNext() {
      if (currentIndex >= items.length) return;
      const idx = currentIndex++;

      Promise.resolve(asyncFn(items[idx]))
        .then(res => {
          results[idx] = res;
          completedCount++;
          if (completedCount === items.length) {
            resolve(results);
          } else {
            launchNext();
          }
        })
        .catch(reject);
    }

    const initialBatch = Math.min(limit, items.length);
    for (let i = 0; i < initialBatch; i++) {
      launchNext();
    }
  });
}

function debounce(fn, delayMs) {
  let timerId = null;
  return function(...args) {
    if (timerId) clearTimeout(timerId);
    timerId = setTimeout(() => {
      fn.apply(this, args);
    }, delayMs);
  };
}

function maxSubarraySum(nums) {
  let maxCurrent = nums[0];
  let maxGlobal = nums[0];

  for (let i = 1; i < nums.length; i++) {
    maxCurrent = Math.max(nums[i], maxCurrent + nums[i]);
    if (maxCurrent > maxGlobal) {
      maxGlobal = maxCurrent;
    }
  }

  return maxGlobal;
}

function compressString(str) {
  if (!str || str.length <= 2) return str;
  let compressed = "";
  let count = 1;

  for (let i = 0; i < str.length; i++) {
    if (str[i] === str[i + 1]) {
      count++;
    } else {
      compressed += str[i] + count;
      count = 1;
    }
  }

  return compressed.length < str.length ? compressed : str;
}

function isValidBrackets(str) {
  const stack = [];
  const map = { ')': '(', '}': '{', ']': '[' };

  for (const char of str) {
    if (char === '(' || char === '{' || char === '[') {
      stack.push(char);
    } else if (map[char]) {
      if (stack.pop() !== map[char]) return false;
    }
  }

  return stack.length === 0;
}

function findTargetPair(arr, target) {
  let left = 0;
  let right = arr.length - 1;

  while (left < right) {
    const sum = arr[left] + arr[right];
    if (sum === target) {
      return [left, right];
    } else if (sum < target) {
      left++;
    } else {
      right--;
    }
  }
  return null;
}

